FILES = {
    'src/enrichment/hp_analysis.py': {'before_sha256s': ['e443998a3f6ace27b88e4fe6071a4bdd67e8850897cd8943f36588b9f7f8a7db', '8458b0e44c41e5d162bb6d72b72d33efccca9913a43733676c9db7386e749c60'], 'content': '"""公式医院の本人確認、ページ構造の解析、媒体の帰属確認。"""\nfrom dataclasses import dataclass, field\nfrom urllib.parse import urlparse, urljoin, urldefrag\nimport re\nimport unicodedata\nfrom bs4 import BeautifulSoup\nfrom src.normalizer.clinic_name import normalize_clinic_name, normalize_person\nfrom src.normalizer.address import normalize_address\nfrom src.normalizer.phone import normalize_phone\n\nNON_OFFICIAL = {"doctorsfile.jp","medicaldoc.jp","epark.jp","caloo.jp","caloo.com","mynavi.jp","mynavi-ms.jp",\n               "instagram.com","facebook.com","x.com","twitter.com","youtube.com","youtu.be","tiktok.com",\n               "tokyo-doctors.com","kanagawa-doctors.com","chiba-doctors.com","byoinnavi.jp","hospita.jp",\n               "qlife.jp","scuel.me","haisha-yoyaku.jp","itp.ne.jp","maps.google.com","google.com","yahoo.co.jp",\n               "job-medley.com","senshin-daido-life.jp","fdoc.jp","gmo-clinic-map.com","web-clover.net"}\n\n\ndef host(url):\n    try:\n        return (urlparse(url).hostname or "").lower().rstrip(".")\n    except ValueError:\n        return ""\n\n\ndef domain_is(url, domain):\n    h = host(url)\n    return h == domain or h.endswith("."+domain)\n\n\ndef is_official_candidate(url):\n    p = urlparse(url)\n    return p.scheme in {"http","https"} and bool(host(url)) and not any(domain_is(url,d) for d in NON_OFFICIAL)\n\n\ndef canonical_page(url):\n    p = urlparse(urldefrag(url)[0])\n    if p.scheme not in {"http","https"} or not p.hostname:\n        return ""\n    # 計測パラメータとクエリの無限ループを避ける。通常HTMLページだけを対象。\n    return p._replace(query="",fragment="").geturl()\n\n\n@dataclass\nclass Page:\n    url: str\n    html: str\n    title: str = ""\n    text: str = ""\n    main_text: str = ""\n    headings: str = ""\n    links: list = field(default_factory=list)\n\n    def __post_init__(self):\n        soup = BeautifulSoup(self.html,"html.parser")\n        self.title = soup.title.get_text(" ",strip=True) if soup.title else ""\n        self.headings = " ".join(x.get_text(" ",strip=True) for x in soup.select("h1,h2"))\n        self.links = [{"url":urljoin(self.url,a.get("href","")),"text":a.get_text(" ",strip=True)} for a in soup.select("a[href]")]\n        for x in soup.select("script,style,noscript,template"):\n            x.decompose()\n        self.text = soup.get_text(" ",strip=True)\n        for x in soup.select("nav,footer,header,aside,[role=navigation]"):\n            x.decompose()\n        self.main_text = soup.get_text(" ",strip=True)\n\n    def evidence(self):\n        return {"url":self.url,"title":self.title,"headings":self.headings[:2000],"text":self.main_text[:15000]}\n\n\ndef identity(record, page, official=True):\n    if official and not is_official_candidate(page.url):\n        return {"verified":False,"score":0,"reasons":["外部媒体・口コミ・SNSは公式HPとして採用しない"]}\n    text = unicodedata.normalize("NFKC",page.text)\n    name = normalize_clinic_name(record.get("clinic_name"))\n    # 外部媒体の本文に複数医院があるだけでは本人とみなさない。\n    name_scope = page.title+" "+page.headings\n    name_ok = bool(name and len(name)>=3 and name in normalize_clinic_name(name_scope))\n    phone = normalize_phone(record.get("phone"))\n    found_phones = {normalize_phone(m[0]) for m in re.finditer(r"(?<!\\d)0\\d[\\d()\\s\\-－ー]{6,18}\\d(?!\\d)",text)}\n    soup = BeautifulSoup(page.html,"html.parser")\n    found_phones.update(normalize_phone(x.get("href","")[4:]) for x in soup.select(\'a[href^="tel:"]\'))\n    exact_phone_pattern = r"(?<!\\d)"+r"[\\s()\\-－ー]*".join(re.escape(d) for d in phone)+r"(?!\\d)" if phone else r"(?!)"\n    phone_ok = bool(phone and len(phone)>=9 and (phone in found_phones or re.search(exact_phone_pattern,text)))\n    address = normalize_address(record.get("address"))\n    addr_ok = bool(len(address)>=8 and address in normalize_address(text))\n    person = normalize_person(record.get("manager_name"))\n    person_ok = bool(person and len(person)>=3 and person in normalize_person(text))\n    reasons = [s for ok,s in [(phone_ok,"電話番号一致"),(name_ok,"医院名がページ見出しに一致"),(addr_ok,"住所一致"),(person_ok,"院長名一致")] if ok]\n    verified = name_ok and (phone_ok or addr_ok)\n    return {"verified":bool(verified),"score":50*phone_ok+40*name_ok+30*addr_ok+20*person_ok,\n            "reasons":reasons or ["医院の本人確認情報が不足"],"phone_match":phone_ok,"name_match":name_ok,"address_match":addr_ok}\n\n\ndef keyword_match(keyword, text):\n    keyword,text = unicodedata.normalize("NFKC",keyword),unicodedata.normalize("NFKC",text)\n    if re.fullmatch(r"[A-Za-z0-9]+",keyword):\n        return len(re.findall(r"(?<![A-Za-z0-9])"+re.escape(keyword)+r"(?![A-Za-z0-9])",text,re.I))\n    return len(re.findall(r"\\s*".join(map(re.escape,keyword.split())),text,re.I))\n'},
    'src/enrichment/researcher.py': {'before_sha256s': ['012a53892ed76eb2917c31da341737db0045b1738302e714aa7551acd866d960', '3b4a85fe67f36a02c3975cf695686c0ac7226962fced794cc766dd24d50f554f'], 'content': '"""1医院単位で取得・判定。HP/EPARK/外部媒体は独立したバッチ。"""\nimport re\nimport unicodedata\nfrom src.enrichment.hp_analysis import Page,identity,is_official_candidate,host,canonical_page\nfrom src.enrichment.safe_web import SafeFetcher,WebError,crawl\nfrom src.enrichment.search_provider import BudgetReached\nfrom src.enrichment.epark_checker import canonical_epark_url\nfrom src.scoring.research_scoring import analyze,media_signals,dedupe_signals,hot_status\nfrom src.master.store import now\n\n\nclass Stopped(Exception):\n    pass\n\n\ndef query_for(record,suffix=""):\n    name = str(record.get("clinic_name","")).replace(\'"\'," ").strip()\n    phone = re.sub(r"[^0-9]","",str(record.get("phone", "")))\n    return f\'"{name}" "{phone}" {suffix}\'.strip() if phone else f\'"{name}" {record.get("address","")} {suffix}\'.strip()\n\n\ndef hp_fallback_query(record):\n    # 正式法人名・旧電話番号で公式HPが見つからないときだけ、医院名＋所在地で1回補完。\n    name = unicodedata.normalize("NFKC",str(record.get("clinic_name", ""))).replace(\'"\'," ").strip()\n    name = re.sub(r"^(?:(?:社会|特定)?医療法人(?:社団|財団)?)[\\s\u3000]*[^\\s\u3000]*?会[\\s\u3000]*", "", name)\n    name = re.sub(r"\\s+", " ", name).strip()\n    return query_for({**record,"clinic_name":name,"phone":""},"公式ホームページ")\n\n\ndef retained_media_signals(record):\n    # HPとは独立に確認した外部媒体の結果を、HP再調査で消さない。\n    return dedupe_signals([s for s in (record or {}).get("marketing_signals",[]) if isinstance(s,dict) and\n        s.get("evidence_type") in {"検索結果の医院名・電話/住所一致","Caloo Plus明記・医院本人確認","制作実績・医院本人確認"}])\n\n\ndef empty_hp_result(status,record=None):\n    # 再調査で本人確認に失敗した場合、旧HP由来の自動判定を現行結果に残さない。\n    # 元CSV・手動修正・EPARKの状態・過去の調査履歴は別管理のまま保持する。\n    signals = retained_media_signals(record)\n    return {"hp_status":status,"hp_verified":False,"hp_url":"","hp_checked_at":now(),\n            "hp_rank":"NO_HP" if status=="NOT_FOUND" else "UNKNOWN","hp_score":0,"hp_rank_reasons":[],\n            "hp_match_score":0,"hp_match_reason":[],"hp_identity_pages":[],"hp_candidates":[],"crawl_errors":[],\n            "treatment_categories":[],"treatment_evidence":[],"treatment_confidence":{},\n            "marketing_signals":signals,"marketing_signal_count":len(signals),"hot_status":hot_status(len(signals)),"research_status":status}\n\n\nclass Researcher:\n    def __init__(self,search,fetcher=None,max_pages=20,should_stop=lambda:False):\n        self.search = search\n        self.fetcher = fetcher or SafeFetcher()\n        self.max_pages = max_pages\n        self.should_stop = should_stop\n\n    def checkpoint(self):\n        if self.should_stop():\n            raise Stopped()\n\n    def hp(self,record,force=False):\n        self.checkpoint()\n        results = []\n        candidates = []\n        existing = record.get("hp_url") or record.get("hp_candidate_url")\n        if existing and is_official_candidate(existing):\n            candidates.append(existing)\n        failures,reviews,seen = [],[],set()\n        queries = iter([query_for(record),hp_fallback_query(record)])\n        while True:\n            for url in candidates:\n                self.checkpoint()\n                key = canonical_page(url)\n                if key in seen:\n                    continue\n                seen.add(key)\n                try:\n                    page = self.fetcher.fetch(url)\n                    check = identity(record,page)\n                    if not is_official_candidate(page.url):\n                        reviews.append({"url":page.url,**check})\n                        continue\n                    support = []\n                    if not check["verified"]:\n                        # トップで住所・電話が不足する医院は同一HPの概要・アクセスを最大2ページ確認。\n                        links = [a["url"] for a in page.links if host(a["url"])==host(page.url) and re.search(r"アクセス|医院概要|医院紹介|contact|access|about",a["text"]+a["url"],re.I)]\n                        for link in list(dict.fromkeys(links))[:2]:\n                            self.checkpoint()\n                            try:\n                                support.append(self.fetcher.fetch(link,allowed_host=host(page.url)))\n                            except WebError:\n                                pass\n                        if support:\n                            check = identity(record,Page(page.url,page.html+"\\n"+"\\n".join(p.html for p in support)))\n                    if not check["verified"]:\n                        reviews.append({"url":page.url,**check})\n                        continue\n                    pages,errors = crawl(page,self.fetcher,self.max_pages,self.should_stop)\n                    self.checkpoint()\n                    # 途中停止なら完了扱いにせず、検索キャッシュを使って再開する。\n                    for p in support:\n                        if p.url not in {x.url for x in pages}:\n                            pages.append(p)\n                    result = analyze(record,pages,results)\n                    signals = dedupe_signals(result["marketing_signals"]+retained_media_signals(record))\n                    result.update(marketing_signals=signals,marketing_signal_count=len(signals),hot_status=hot_status(len(signals)))\n                    result.update(hp_url=page.url,hp_status="VERIFIED",hp_verified=True,hp_match_score=check["score"],\n                                  hp_match_reason=check["reasons"],hp_checked_at=now(),hp_identity_pages=[page.url]+[p.url for p in support],\n                                  crawl_errors=errors,research_status="SUCCESS",research_error="",hp_candidates=reviews)\n                    return result,[p.evidence() for p in pages]\n                except WebError as exc:\n                    failures.append({"url":url,"reason":str(exc)})\n            query = next(queries,None)\n            if query is None:\n                break\n            self.checkpoint()\n            batch = self.search.search(query,force=force)\n            results.extend(batch)\n            candidates = list(dict.fromkeys(r.get("url","") for r in batch if is_official_candidate(r.get("url",""))))[:5]\n        status = "REVIEW" if reviews else "ERROR" if failures else "NOT_FOUND"\n        signals = dedupe_signals(media_signals(record,results)+retained_media_signals(record))\n        return {**empty_hp_result(status,record),"hp_candidates":reviews,"crawl_errors":failures,\n                "hp_match_reason":["検索した範囲で公式HPを発見できませんでした。" if status=="NOT_FOUND" else "候補ページの本人確認・取得を完了できませんでした。"],\n                "marketing_signals":signals,"marketing_signal_count":len(signals),"hot_status":hot_status(len(signals)),"research_error":""},[]\n\n    def epark(self,record,force=False):\n        self.checkpoint()\n        results = self.search.search(query_for(record,"site:epark.jp"),force=force)\n        urls = list(dict.fromkeys(canonical_epark_url(r.get("url","")) for r in results))\n        urls = [u for u in urls if u]\n        if not urls:\n            # 電話による検索で出なかった場合だけ住所で補完。\n            self.checkpoint()\n            name = str(record.get("clinic_name","")).replace(\'"\',\' \')\n            results2 = self.search.search(f\'"{name}" {record.get("address","")} site:epark.jp\',force=force)\n            results += results2\n            urls = list(dict.fromkeys(canonical_epark_url(r.get("url","")) for r in results2))\n            urls = [u for u in urls if u]\n        verified,issues = [],[]\n        for url in urls[:3]:\n            self.checkpoint()\n            try:\n                page = self.fetcher.fetch(url)\n                if not canonical_epark_url(page.url):\n                    raise WebError("EPARK以外の移転先です。")\n                check = identity(record,page,official=False)\n                if check["verified"]:\n                    verified.append((url,check))\n                else:\n                    issues.append({"url":url,"reason":"医院の本人確認不足"})\n            except WebError as exc:\n                # 取得制限時は検索結果だけで確定せず候補として保存。\n                issues.append({"url":url,"reason":str(exc)})\n        if len(verified)==1:\n            url,check = verified[0]\n            return {"epark_url":url,"epark_found":True,"epark_status":"VERIFIED","epark_match_score":check["score"],\n                    "epark_match_reason":check["reasons"],"epark_checked_at":now(),"epark_contract":"UNKNOWN",\n                    "epark_issues":issues,"research_status":"SUCCESS"},None\n        status = "REVIEW" if urls else "NOT_FOUND"\n        return {"epark_url":"","epark_found":None,"epark_status":status,"epark_candidates":urls,\n                "epark_issues":issues,"epark_checked_at":now(),"epark_contract":"UNKNOWN","research_status":status},None\n\n    def media(self,record,force=False):\n        self.checkpoint()\n        results = self.search.search(query_for(record,"掲載 記事 制作実績"),force=force)\n        auto = media_signals(record,results)\n        # 1回の一般検索で複数媒体を分類。媒体ごとに別検索しない。\n        known = record.get("marketing_signals",[])\n        known = [s for s in known if isinstance(s,dict) and s.get("evidence_type")!="検索結果の医院名・電話/住所一致"]\n        return {"marketing_signals":dedupe_signals(known+auto),"media_checked_at":now(),"media_results":results,"research_status":"SUCCESS"},None\n\n    def run(self,kind,record,force=False):\n        if kind not in {"hp","epark","media"}:\n            raise ValueError("調査の種類を選んでください。")\n        return getattr(self,kind)(record,force)\n'},
    'src/scoring/research_scoring.py': {'before_sha256s': ['b5780127348a428810af44f5f2a16da3e794ad51bad2adcfdffb91739d00a09e', '90b38fb4311fb5ddd0b322efcd164e8ad18cdb9be911c761b47e3384499120e2'], 'content': '"""治療、HP機能、集客施策を別々に評価。シグナルは種類ごとに常に1点。"""\nfrom copy import deepcopy\nfrom functools import lru_cache\nfrom urllib.parse import urlparse\nimport re\nfrom bs4 import BeautifulSoup\nfrom src.enrichment.hp_analysis import identity, Page, host, domain_is, keyword_match, is_official_candidate\nfrom src.enrichment.consultation_schedule import SIGNAL_NAME as MIDDAY_SIGNAL,midday_procedure\nfrom src.utils.config import ROOT, read_config\nfrom src.utils.date_utils import today_japan\n\nSIGNAL_NAMES = ["Googleスポンサー広告確認済み","EPARK課金済み確認","Doctors File掲載","Medical DOC掲載","マイナビ記事掲載",\n                "HP制作会社の制作実績","地域ドクターズ掲載","AIチャット導入","YouTube公式運用","TikTok公式運用","漫画コンテンツ",\n                "治療専用LP","治療専門サイト","Caloo Plus","眼科Doc等専門媒体","その他有料施策・集客ツール",MIDDAY_SIGNAL]\nMEDIA = {"doctorsfile.jp":"Doctors File掲載","medicaldoc.jp":"Medical DOC掲載","mynavi.jp":"マイナビ記事掲載",\n         "mynavi-ms.jp":"マイナビ記事掲載","tokyo-doctors.com":"地域ドクターズ掲載","kanagawa-doctors.com":"地域ドクターズ掲載",\n         "chiba-doctors.com":"地域ドクターズ掲載","ganka-doc.com":"眼科Doc等専門媒体"}\n\n\ndef signal(name, url, evidence_type, evidence, **kwargs):\n    return {"name":name,"status":"CONFIRMED","evidence_url":url,"evidence_type":evidence_type,"evidence":evidence,**kwargs}\n\n\ndef dedupe_signals(signals):\n    unique = {}\n    for s in signals:\n        if s.get("name") in SIGNAL_NAMES and s.get("status")=="CONFIRMED":\n            unique.setdefault(s["name"],s)\n    return [unique[n] for n in SIGNAL_NAMES if n in unique]\n\n\ndef hot_status(count):\n    return "かなりアツい" if count>=3 else "アツい" if count==2 else "集客投資シグナルあり" if count==1 else "通常"\n\n\ndef treatments(pages, config=None):\n    cfg = config or read_config(ROOT/"config/treatment_keywords.yml")\n    pages = [p for p in pages if is_official_candidate(p.url)]\n    evidence = []\n    for category,keywords in cfg.items():\n        for page in pages:\n            for keyword in keywords:\n                heading = keyword_match(keyword,page.title+" "+page.headings)\n                body = keyword_match(keyword,page.main_text)\n                if not heading and not body:\n                    continue\n                # 否定だけの行は治療提供の証拠にしない。\n                sentences = re.split(r"[。\\n]",page.main_text)\n                affirmative = [s for s in sentences if keyword_match(keyword,s) and not re.search(r"行っていません|実施していません|対応していません|取り扱っていません|他院をご紹介|他院に紹介",s)]\n                if body and not affirmative:\n                    continue\n                confidence = .9 if heading and body else .75 if body>=2 else .4\n                evidence.append({"category":category,"url":page.url,"keyword":keyword,"confidence":confidence,\n                                 "reason":"見出しと本文" if heading and body else "本文複数回" if body>=2 else "弱い言及・要確認"})\n    categories = [k for k in cfg if any(e["category"]==k and e["confidence"]>=.7 for e in evidence)]\n    return {"treatment_categories":categories,"treatment_evidence":evidence,\n            "treatment_confidence":{k:max(e["confidence"] for e in evidence if e["category"]==k) for k in cfg if any(e["category"]==k for e in evidence)}}\n\n\ndef hp_signals(record,pages):\n    found = []\n    for page in pages:\n        if not is_official_candidate(page.url):\n            continue\n        soup = BeautifulSoup(page.html,"html.parser")\n        midday = midday_procedure(page.html)\n        if midday:\n            found.append(signal(MIDDAY_SIGNAL,page.url,midday["evidence_type"],midday["evidence"],\n                **{k:v for k,v in midday.items() if k not in {"evidence_type","evidence"}}))\n        for a in page.links:\n            url,label = a["url"],a["text"]\n            if (domain_is(url,"youtube.com") and re.search(r"/(?:@|channel/|c/|user/)",urlparse(url).path)):\n                found.append(signal("YouTube公式運用",page.url,"公式HPのチャンネルリンク",url))\n            if domain_is(url,"tiktok.com") and "/@" in urlparse(url).path:\n                found.append(signal("TikTok公式運用",page.url,"公式HPのアカウントリンク",url))\n            if re.search(r"専門サイト|専門ホームページ",label) and host(url) and host(url)!=host(page.url):\n                found.append(signal("治療専門サイト",page.url,"公式HPからの専用サイトリンク",url))\n            if re.search(r"漫画|マンガ|コミック",label) and re.search(r"manga|comic|漫画|マンガ",url,re.I):\n                found.append(signal("漫画コンテンツ",page.url,"専用コンテンツリンク",url))\n        for iframe in soup.select("iframe[src]"):\n            url = iframe.get("src", "")\n            if (domain_is(url,"youtube.com") or domain_is(url,"youtube-nocookie.com")) and re.search(r"当院|医院紹介|院長|クリニック紹介|公式",iframe.get("title", "")):\n                found.append(signal("YouTube公式運用",page.url,"医院紹介の動画埋込",url))\n        if re.search(r"漫画でわかる|マンガでわかる|コミック",page.headings) and (soup.select("img") or len(page.main_text)>100):\n            found.append(signal("漫画コンテンツ",page.url,"専用見出し・コンテンツ","漫画専用コンテンツ"))\n        if re.search(r"/(?:lp|landing|campaign)(?:/|[-_.]|$)",urlparse(page.url).path,re.I) and identity(record,page)["verified"]:\n            found.append(signal("治療専用LP",page.url,"LP本人確認","医院名と電話/住所を確認"))\n        embeds = " ".join(str(t) for t in soup.select("script,iframe,[data-chatbot-id],[data-ai-chat],[data-chat-widget]"))\n        if re.search(r"(?:udify\\.app|dify\\.ai|difyChatbotConfig|data-ai-chat|data-chatbot-id)",embeds,re.I):\n            service = "Dify" if re.search(r"dify|udify",embeds,re.I) else "AIチャット（サービス名未特定）"\n            found.append(signal("AIチャット導入",page.url,"script/iframe/data属性","AIチャット埋込を確認",service_name=service))\n        elif re.search(r"AIチャット|AI相談|24時間.*AI",page.text,re.I) and re.search(r"chatbot|chat-widget|chatplus|chatform|chatbase",embeds,re.I):\n            found.append(signal("AIチャット導入",page.url,"AI記載とチャット埋込","AIの明記とウィジェットを確認",service_name="AIチャット（サービス名未特定）"))\n    return dedupe_signals(found)\n\n\ndef media_signals(record, results):\n    found = []\n    for r in results:\n        url,title,content = r.get("url",""),r.get("title",""),r.get("content","")\n        import html\n        page = Page(url,f"<title>{html.escape(title)}</title><h1>{html.escape(title)}</h1><main>{html.escape(content)}</main>")\n        if not identity(record,page,official=False)["verified"]:\n            continue\n        name = next((s for domain,s in MEDIA.items() if domain_is(url,domain)),None)\n        if name:\n            found.append(signal(name,url,"検索結果の医院名・電話/住所一致",content[:500]))\n        if (domain_is(url,"caloo.jp") or domain_is(url,"caloo.com")) and re.search(r"caloo\\s*plus|カループラス",title+" "+content,re.I):\n            found.append(signal("Caloo Plus",url,"Caloo Plus明記・医院本人確認",content[:500]))\n        if re.search(r"制作実績|導入事例",title) and re.search(r"ホームページ|Webサイト|WEBサイト|HP制作",title+content):\n            found.append(signal("HP制作会社の制作実績",url,"制作実績・医院本人確認",content[:500]))\n    return dedupe_signals(found)\n\n\ndef rank_hp(pages, treatment, signals, config=None):\n    cfg = config or read_config(ROOT/"config/hp_ranking.yml")\n    pages = [p for p in pages if is_official_candidate(p.url)]\n    if not pages:\n        return {"hp_rank":"NO_HP","hp_score":0,"hp_rank_reasons":[]}\n    html = "\\n".join(p.html for p in pages)\n    text = "\\n".join(p.main_text for p in pages)\n    soup = BeautifulSoup(html,"html.parser")\n    links = [a for p in pages for a in p.links]\n    treatment_urls = {e["url"] for e in treatment.get("treatment_evidence",[]) if e["confidence"]>=.7}\n    features = {\n        "HTTPS":pages[0].url.startswith("https://"), "スマホviewport":bool(soup.select(\'meta[name="viewport"]\')),\n        "Web予約導線":any(re.search(r"予約|受付|reserve|reservation|booking",a["text"]+a["url"],re.I) for a in links),\n        "LINE導線":any(domain_is(a["url"],"line.me") or domain_is(a["url"],"lin.ee") for a in links),\n        "治療専用ページ":bool(treatment_urls), "院長プロフィール":bool(re.search(r"院長紹介|院長プロフィール|院長挨拶|院長ご挨拶",text)),\n        "写真":len(soup.select("img"))>=3, "料金情報":bool(re.search(r"料金|費用|価格|円[（(税込]",text)),\n        "問合せCTA":any(re.search(r"お問い合わせ|問合せ|tel:",a["text"]+a["url"]) for a in links),\n        "SNS導線":any(any(domain_is(a["url"],d) for d in ["instagram.com","youtube.com","tiktok.com","facebook.com","x.com"]) for a in links),\n        "独自LP・専門サイト":any(s["name"] in {"治療専用LP","治療専門サイト"} for s in signals)}\n    reasons = [{"feature":k,"points":int(cfg["weights"].get(k,0))} for k,v in features.items() if v]\n    score = sum(r["points"] for r in reasons)\n    rank = next((r for r in ["A","B","C","D"] if score>=cfg["thresholds"][r]),"D")\n    return {"hp_rank":rank,"hp_score":score,"hp_rank_reasons":reasons,"hp_rank_version":cfg["version"]}\n\n\ndef analyze(record,pages,results=()):\n    from src.enrichment.profiles import estimate_profile_age\n    treatment = treatments(pages)\n    signals = dedupe_signals(hp_signals(record,pages)+media_signals(record,results))\n    return {**treatment, **rank_hp(pages,treatment,signals), **estimate_profile_age(record,pages),\n            "marketing_signals":signals, "marketing_signal_count":len(signals),"hot_status":hot_status(len(signals))}\n\n\ndef finalize_result(data):\n    data = deepcopy(data)\n    signals = data.get("marketing_signals",[])\n    if signals and isinstance(signals[0],str):\n        signals = [signal(n,"","手動確認","手動で選択したシグナル") for n in signals]\n    # 契約/広告の専用状態を唯一の正とし、一般シグナルチェックでの裏口を作らない。\n    signals = [s for s in signals if s.get("name") not in {"Googleスポンサー広告確認済み","EPARK課金済み確認"}]\n    if data.get("epark_contract")=="PAID":\n        signals.append(signal("EPARK課金済み確認",data.get("epark_url",""),"契約状態の確認","課金済み確認"))\n    if data.get("google_ads_status")=="CONFIRMED":\n        signals.append(signal("Googleスポンサー広告確認済み",data.get("hp_url",""),"手動広告確認","Googleスポンサー広告確認済み"))\n    signals = dedupe_signals(signals)\n    data.update(marketing_signals=signals,marketing_signal_count=len(signals),hot_status=hot_status(len(signals)))\n    data.setdefault("hp_status","UNRESEARCHED")\n    if data["hp_status"]=="NOT_FOUND" and "hp_rank" not in data.get("manual_fields",[]):\n        data["hp_rank"] = "NO_HP"\n    if data["hp_status"]=="VERIFIED" and not data.get("hp_url"):\n        data["hp_status"] = "REVIEW"\n    data["hp_verified"] = data["hp_status"]=="VERIFIED"\n    data.setdefault("epark_contract","UNKNOWN")\n    data.setdefault("google_ads_status","UNKNOWN")\n    return data\n'},
    'src/master/jobs.py': {'before_sha256s': ['81c1f7767699d71ff0903ac0b109cd8fd1621f05a803dc40cbeeae0c17c089f9', 'c7525897310bb3d2b3cb32d0028a656cdab31070f8a91a66bb93b9cb292cd6ed'], 'content': '"""永続ジョブ＋1医院単位の確定。プロセス間ロックで二重実行を防ぐ。"""\nfrom threading import Thread,Lock\nimport uuid\nimport json\nfrom filelock import FileLock,Timeout\nfrom src.master.store import now,dumps\nfrom src.master.filters import where\nfrom src.enrichment.search_provider import CachedSearch,BudgetReached,SearchError\nfrom src.enrichment.researcher import Researcher,Stopped,empty_hp_result\n\n\ndef create_job(store,filters,kind="hp",limit=100,max_searches=100,force=False,max_pages=20):\n    if kind not in {"hp","epark","media"}:\n        raise ValueError("調査種類を確認してください。")\n    limit = min(500,max(1,int(limit)))\n    max_searches = min(1000,max(0,int(max_searches)))\n    sql,args = where(filters)\n    if not force:\n        sql += {"hp":" AND hp_status=\'UNRESEARCHED\'", "epark":" AND json_extract(effective_json,\'$.epark_checked_at\') IS NULL",\n                "media":" AND json_extract(effective_json,\'$.media_checked_at\') IS NULL"}[kind]\n    jid = uuid.uuid4().hex\n    with store.connect() as c:\n        c.execute("BEGIN IMMEDIATE")\n        ids = [r[0] for r in c.execute("SELECT id FROM clinics WHERE "+sql+" ORDER BY (uuid<>\'\') DESC,is_new DESC,id LIMIT ?",(*args,limit))]\n        if not ids:\n            raise ValueError("指定した条件の未調査医院がありません。条件を見直すか、強制再調査を選択してください。")\n        c.execute("INSERT INTO research_jobs(id,kind,options_json,max_searches,created_at,updated_at) VALUES(?,?,?,?,?,?)",\n                  (jid,kind,dumps({"force":bool(force),"max_pages":max_pages}),max_searches,now(),now()))\n        c.executemany("INSERT INTO research_job_items(job_id,clinic_id) VALUES(?,?)",[(jid,i) for i in ids])\n    return jid\n\n\ndef job_status(store,jid):\n    with store.connect() as c:\n        r = c.execute("SELECT * FROM research_jobs WHERE id=?",(jid,)).fetchone()\n        if not r:\n            raise ValueError("調査履歴が見つかりません。")\n        result = dict(r)\n        result["counts"] = {r[0]:r[1] for r in c.execute("SELECT state,count(*) FROM research_job_items WHERE job_id=? GROUP BY state",(jid,))}\n        result["results"] = {r[0]:r[1] for r in c.execute("SELECT result,count(*) FROM research_job_items WHERE job_id=? AND state=\'DONE\' GROUP BY result",(jid,))}\n        result["total"] = sum(result["counts"].values())\n        return result\n\n\ndef recent_jobs(store):\n    with store.connect() as c:\n        return [dict(r) for r in c.execute("SELECT * FROM research_jobs ORDER BY created_at DESC,id DESC LIMIT 20")]\n\n\ndef pause_job(store,jid):\n    with store.connect() as c:\n        c.execute("UPDATE research_jobs SET status=\'PAUSED\',updated_at=? WHERE id=? AND status<>\'COMPLETED\'",(now(),jid))\n\n\ndef job_limit(store,jid,limit):\n    with store.connect() as c:\n        c.execute("UPDATE research_jobs SET max_searches=?,updated_at=? WHERE id=?",(max(0,int(limit)),now(),jid))\n\n\ndef run_job(store,jid,provider,fetcher=None):\n    try:\n        with FileLock(str(store.path)+".research.lock",timeout=0):\n            _run_locked(store,jid,provider,fetcher)\n    except Timeout:\n        return False\n    return True\n\n\ndef _run_locked(store,jid,provider,fetcher):\n    with store.connect() as c:\n        c.execute("BEGIN IMMEDIATE")\n        job = dict(c.execute("SELECT * FROM research_jobs WHERE id=?",(jid,)).fetchone())\n        if job["status"]=="COMPLETED":\n            return\n        # ロック取得できた時点で旧プロセスの実行はない。未完了行だけを回復。\n        c.execute("UPDATE research_job_items SET state=\'PENDING\' WHERE state=\'RUNNING\'")\n        c.execute("UPDATE research_jobs SET status=\'PAUSED\' WHERE status=\'RUNNING\'")\n        c.execute("UPDATE research_jobs SET status=\'RUNNING\',updated_at=? WHERE id=?",(now(),jid))\n    search = CachedSearch(store,provider,jid)\n    options = json.loads(job["options_json"])\n    def stopped():\n        return job_status(store,jid)["status"]!="RUNNING"\n    researcher = Researcher(search,fetcher,max_pages=options.get("max_pages",20),should_stop=stopped)\n    while not stopped():\n        with store.connect() as c:\n            c.execute("BEGIN IMMEDIATE")\n            row = c.execute("SELECT clinic_id FROM research_job_items WHERE job_id=? AND state=\'PENDING\' ORDER BY clinic_id LIMIT 1",(jid,)).fetchone()\n            if row is None:\n                c.execute("UPDATE research_jobs SET status=\'COMPLETED\',updated_at=? WHERE id=?",(now(),jid))\n                return\n            cid = row[0]\n            c.execute("UPDATE research_job_items SET state=\'RUNNING\' WHERE job_id=? AND clinic_id=?",(jid,cid))\n        record = {}\n        try:\n            record = store.get(cid)\n            # 手動値は解析入力としては使うが、自動シグナルの保存に手動値をコピーしない。\n            with store.connect() as c:\n                auto = c.execute("SELECT result_json FROM research_results WHERE clinic_id=?",(cid,)).fetchone()\n                record["marketing_signals"] = json.loads(auto[0]).get("marketing_signals",[]) if auto else []\n            result,pages = researcher.run(job["kind"],record,options.get("force",False))\n            store.save_research(cid,result,pages)\n            status,note = result.get("research_status","SUCCESS"),""\n        except (BudgetReached,Stopped) as exc:\n            with store.connect() as c:\n                c.execute("UPDATE research_job_items SET state=\'PENDING\',note=? WHERE job_id=? AND clinic_id=?",(str(exc),jid,cid))\n                c.execute("UPDATE research_jobs SET status=?,updated_at=? WHERE id=?",("BUDGET" if isinstance(exc,BudgetReached) else "PAUSED",now(),jid))\n            return\n        except Exception as exc:\n            # 接続の秘密や生Tracebackを画面/DBへ残さない。\n            status = "ERROR"\n            note = str(exc) if isinstance(exc,SearchError) else "この医院の調査でエラーが発生しました。再調査または手動確認を行ってください。"\n            safe_result = {"research_status":"ERROR","research_error":note}\n            if job["kind"]=="hp":\n                safe_result.update(empty_hp_result("ERROR",record))\n            else:\n                safe_result[job["kind"]+"_checked_at"] = now()\n            store.save_research(cid,safe_result,[] if job["kind"]=="hp" else None)\n        with store.connect() as c:\n            c.execute("UPDATE research_job_items SET state=\'DONE\',result=?,note=? WHERE job_id=? AND clinic_id=?",(status,note,jid,cid))\n            c.execute("UPDATE research_jobs SET updated_at=? WHERE id=?",(now(),jid))\n\n\nclass JobRunner:\n    def __init__(self):\n        self.thread = None\n        self.lock = Lock()\n\n    def start(self,store,jid,provider):\n        with self.lock:\n            if self.thread and self.thread.is_alive():\n                raise ValueError("調査中です。一時停止してから別の調査を開始してください。")\n            self.thread = Thread(target=run_job,args=(store,jid,provider),daemon=True)\n            self.thread.start()\n\n    def running(self):\n        return bool(self.thread and self.thread.is_alive())\n'},
    'config/treatment_keywords.yml': {'before_sha256s': ['811e68a91977e3d229f160bff9be369c49256b53aa28350beb6530e4ffbd22b1', '6c404164268b05d4d5183f939621f3c5111c49bf943887a44f2afd4cf0810dfb'], 'content': '内視鏡: [内視鏡, 胃カメラ, 大腸カメラ, 大腸内視鏡, 大腸ポリープ切除, 日帰りポリープ切除, 鎮静剤 内視鏡]\n白内障: [白内障, 白内障手術, 日帰り白内障手術, 多焦点眼内レンズ, 選定療養 白内障]\n緑内障: [緑内障, 緑内障手術, 緑内障レーザー治療, MIGS, SLT, 低侵襲緑内障手術, iStent]\nICL: [ICL, 眼内コンタクトレンズ]\n糖尿病: [糖尿病内科, 糖尿病専門医, 糖尿病専門外来, 1型糖尿病, インスリン導入, CGM, FreeStyleリブレ, HbA1c当日検査]\n泌尿器科: [尿路結石, 前立腺, 膀胱鏡, ED, 男性更年期]\n循環器内科: [循環器内科, 心エコー, ホルター心電図, 不整脈, 高血圧専門]\n皮膚科: [ニキビ, ニキビ治療, 美容皮膚科, 医療脱毛, シミ治療]\n'},
    'tests/test_v2_network_jobs.py': {'before_sha256s': ['6384d93f7ba03860bb6f46f45e399ccb095a5e76b60eb1422ba00e3c8b3af913', '90e1304e10322d7239b9c4d54b9a08ddf3b4bbdc47f08bd765c5a62aa5dba73c'], 'content': 'import json\nimport socket\nfrom pathlib import Path\nfrom types import SimpleNamespace\nimport pytest\nfrom src.master.store import ClinicStore\nfrom src.master.filters import Filters\nfrom src.master.samples import sample_records,SampleProvider,SampleFetcher\nfrom src.master.jobs import create_job,run_job,job_status,pause_job,job_limit\nfrom src.enrichment.safe_web import validate_url,SafeFetcher,WebResponse,WebError,crawl\nfrom src.enrichment.search_provider import CachedSearch,TavilySearchProvider,SearchError,BudgetReached\nfrom src.enrichment.researcher import Researcher\nfrom src.enrichment.hp_analysis import Page\n\n\n@pytest.fixture\ndef store(tmp_path):\n    return ClinicStore(tmp_path/"clinics.db")\n\n\nclass Provider:\n    def __init__(self,results=(),fail=False):\n        self.calls=0;self.results=list(results);self.fail=fail\n    def search(self,query):\n        self.calls+=1\n        if self.fail:\n            raise SearchError("Tavily接続エラー")\n        return self.results\n\n\ndef test_cache_persists_force_only_and_cap(store):\n    p=Provider([{"url":"https://demo.example/","title":"医院","content":"根拠"}])\n    s=CachedSearch(store,p,max_searches=2)\n    assert s.search("医院名 電話")==p.results\n    assert s.search("医院名 電話")==p.results and p.calls==1\n    s=CachedSearch(ClinicStore(store.path),p,max_searches=2)\n    s.search("医院名 電話")\n    assert p.calls==1\n    s.search("医院名 電話",force=True)\n    assert p.calls==2\n    store.set_setting("monthly_limit",2)\n    with pytest.raises(BudgetReached):\n        s.search("別の医院")\n    assert p.calls==2\n\n\ndef test_failed_search_counts_and_reserve_and_month_boundary(store):\n    p=Provider(fail=True);s=CachedSearch(store,p)\n    store.set_setting("monthly_limit",2)\n    with pytest.raises(SearchError):\n        s.search("失敗")\n    assert s.monthly_usage()==1\n    store.set_setting("external_usage_reserve",1)\n    with pytest.raises(BudgetReached):\n        s.search("別医院")\n    assert p.calls==1\n    with store.connect() as c:\n        c.execute("UPDATE search_usage SET month=\'2000-01\'")\n    assert s.monthly_usage()==0\n\n\ndef test_tavily_basic_api_payload_errors_and_no_key_in_db(store):\n    class Session:\n        def post(self,url,**kwargs):\n            assert url=="https://api.tavily.com/search"\n            assert kwargs["json"]["search_depth"]=="basic"\n            assert kwargs["json"]["auto_parameters"] is False\n            assert kwargs["allow_redirects"] is False\n            return SimpleNamespace(status_code=200,json=lambda:{"results":[{"url":"https://example.com/","title":"確認","content":"医院"}],"api_key":"secret-value"})\n    p=TavilySearchProvider("secret-value",Session())\n    CachedSearch(store,p).search("公開医院名")\n    assert b"secret-value" not in store.backup_bytes()\n\n\n@pytest.mark.parametrize("status",[401,429,432,500,503])\ndef test_tavily_errors_no_retry_no_secret(status):\n    class Session:\n        calls=0\n        def post(self,*a,**kw):\n            self.calls+=1\n            return SimpleNamespace(status_code=status,text="secret-value")\n    session=Session()\n    p=TavilySearchProvider("secret-value",session)\n    with pytest.raises(SearchError) as exc:\n        p.search("医院")\n    assert "secret-value" not in str(exc.value) and session.calls==1\n\n\n@pytest.mark.parametrize("url",["http://127.0.0.1/","http://localhost/","https://x.local/","http://10.1.2.3/","http://192.168.1.1/",\n    "http://169.254.169.254/","http://[::1]/","http://[fc00::1]/","file:///etc/passwd","ftp://example.com/","http://u:p@example.com/","http://example.com:8080/","http://0.0.0.0/"])\ndef test_ssrf_url_block(url):\n    with pytest.raises(WebError):\n        validate_url(url,resolve=False)\n\n\ndef test_ssrf_dns_private_any_address_blocks(monkeypatch):\n    monkeypatch.setattr(socket,"getaddrinfo",lambda *a,**k:[(2,1,6,"",("8.8.8.8",80)),(2,1,6,"",("127.0.0.1",80))])\n    with pytest.raises(WebError):\n        validate_url("http://public.example/")\n\n\nclass Transport:\n    def __init__(self,routes):\n        self.routes=routes;self.calls=[]\n    def get(self,url,timeout,max_bytes):\n        self.calls.append(url)\n        response=self.routes[url]\n        if isinstance(response,Exception):\n            raise response\n        return response\n\n\ndef response(text,status=200,**headers):\n    return WebResponse(status,{"content-type":"text/html; charset=utf-8",**headers},text.encode())\n\n\ndef test_redirect_ssrf_robots_block_size_and_loop():\n    transport=Transport({"https://clinic.example/robots.txt":response("",404),"https://clinic.example/":response("",302,location="http://127.0.0.1/")})\n    fetch=SafeFetcher(transport,interval=0)\n    with pytest.raises(WebError):\n        fetch.fetch("https://clinic.example/")\n    assert all("127.0.0.1" not in url for url in transport.calls)\n    transport=Transport({"https://clinic.example/robots.txt":response("User-agent: *\\nDisallow: /\\n")})\n    with pytest.raises(WebError,match="robots"):\n        SafeFetcher(transport,interval=0).fetch("https://clinic.example/")\n    assert len(transport.calls)==1\n    transport=Transport({"https://clinic.example/robots.txt":response("",404),"https://clinic.example/":response("x"*101)})\n    with pytest.raises(WebError,match="サイズ"):\n        SafeFetcher(transport,max_bytes=100,interval=0).fetch("https://clinic.example/")\n\n\ndef test_crawl_domain_limit_duplicates_failure_continues():\n    first=Page("https://clinic.example/",\'<a href="/treat/">治療</a><a href="/treat/#x">治療</a><a href="/bad/">検査</a><a href="https://other.example/">外部</a><a href="/x.pdf">資料</a>\')\n    class Fetcher:\n        calls=[]\n        def fetch(self,url,allowed_host=None):\n            self.calls.append(url)\n            assert allowed_host=="clinic.example"\n            if "/bad/" in url:\n                raise WebError("通信エラー")\n            return Page(url,\'<a href="/">top</a><a href="/more/">治療</a>\')\n    f=Fetcher();pages,errors=crawl(first,f,max_pages=3)\n    assert len(f.calls)==2\n    assert f.calls.count("https://clinic.example/treat/")==1\n    assert len(errors)==1 and len(pages)==2\n\n\ndef test_403_blocks_host_further_fetch():\n    t=Transport({"https://clinic.example/robots.txt":response("",404),"https://clinic.example/":response("",403)})\n    f=SafeFetcher(t,interval=0)\n    with pytest.raises(WebError):f.fetch("https://clinic.example/")\n    with pytest.raises(WebError):f.fetch("https://clinic.example/second/")\n    assert len(t.calls)==2\n\n\ndef test_hp_not_found_and_error_not_equated(store):\n    researcher=Researcher(CachedSearch(store,Provider()),SampleFetcher())\n    result,_=researcher.hp(sample_records()[0])\n    assert result["hp_status"]=="NOT_FOUND" and result["hp_rank"]=="NO_HP"\n    record=sample_records()[0]\n    result,_=Researcher(CachedSearch(store,Provider([{"url":"https://broken.example/","title":record["clinic_name"],"content":""}])) ,SampleFetcher()).hp(record,force=True)\n    assert result["hp_status"]=="ERROR"\n\n\n@pytest.mark.parametrize("has_hp_link",[True,False])\ndef test_epark_route_identity_never_infers_contract(store,has_hp_link):\n    r=sample_records()[0];url="https://epark.jp/shopinfo/hpl123/"\n    search=CachedSearch(store,Provider([{"url":url,"title":r["clinic_name"],"content":r["phone"]}]))\n    class Fetch:\n        def fetch(self,url):\n            return Page(url,f\'<title>{r["clinic_name"]}</title><p>{r["phone"]} {r["address"]}</p>\'+(\'<a href="https://clinic.example/">HP</a>\' if has_hp_link else \'\'))\n    result,_=Researcher(search,Fetch()).epark(r)\n    assert result["epark_found"] is True and result["epark_contract"]=="UNKNOWN"\n    assert result["epark_url"]==url\n    assert search.used==1\n\n\ndef test_epark_no_results_fallback_two_queries(store):\n    search=CachedSearch(store,Provider())\n    result,_=Researcher(search,SampleFetcher()).epark(sample_records()[0])\n    assert result["epark_status"]=="NOT_FOUND"\n    assert search.used==2\n\n\ndef test_job_budget_pause_resume_done_not_researched(store):\n    store.import_master(sample_records())\n    jid=create_job(store,Filters(active_only=False,hp_only=False),limit=4,max_searches=1,max_pages=2)\n    p=SampleProvider()\n    run_job(store,jid,p,SampleFetcher())\n    job=job_status(store,jid)\n    assert job["status"]=="BUDGET" and job["counts"]["DONE"]==1 and p.calls==1\n    job_limit(store,jid,10)\n    run_job(store,jid,p,SampleFetcher())\n    job=job_status(store,jid)\n    assert job["status"]=="COMPLETED" and job["counts"]["DONE"]==4 and p.calls==5\n    assert job["results"]=={"SUCCESS":3,"NOT_FOUND":1}\n    run_job(store,jid,p,SampleFetcher())\n    assert p.calls==5\n    with pytest.raises(ValueError,match="未調査"):\n        create_job(store,Filters(active_only=False,hp_only=False))\n\n\ndef test_network_error_one_clinic_does_not_stop_batch(store):\n    store.import_master(sample_records()[:2])\n    class FailFirst(SampleProvider):\n        def search(self,query):\n            if "青空" in query:\n                self.calls+=1\n                raise SearchError("通信エラー")\n            return super().search(query)\n    jid=create_job(store,Filters(hp_only=False),max_searches=10)\n    run_job(store,jid,FailFirst(),SampleFetcher())\n    assert job_status(store,jid)["results"]=={"ERROR":1,"SUCCESS":1}\n    assert job_status(store,jid)["status"]=="COMPLETED"\n\n\n@pytest.mark.parametrize("force",[False,True])\ndef test_pause_during_request_replays_cache_but_not_api(store,force):\n    store.import_master(sample_records()[:1])\n    jid=create_job(store,Filters(hp_only=False),max_searches=10,force=force)\n    class Pause(SampleProvider):\n        def search(self,q):\n            result=super().search(q)\n            pause_job(store,jid)\n            return result\n    p=Pause()\n    run_job(store,jid,p,SampleFetcher())\n    assert job_status(store,jid)["status"]=="PAUSED"\n    run_job(store,jid,p,SampleFetcher())\n    assert job_status(store,jid)["status"]=="COMPLETED"\n    assert p.calls==1\n\n\ndef test_crash_recovery_returns_running_item_to_pending(store):\n    store.import_master(sample_records()[:1])\n    jid=create_job(store,Filters(hp_only=False))\n    with store.connect() as c:\n        c.execute("UPDATE research_job_items SET state=\'RUNNING\' WHERE job_id=?",(jid,))\n        c.execute("UPDATE research_jobs SET status=\'RUNNING\' WHERE id=?",(jid,))\n    run_job(store,jid,SampleProvider(),SampleFetcher())\n    assert job_status(store,jid)["status"]=="COMPLETED"\n'},
    'tests/test_v3_hp_false_positives.py': {'before_sha256s': [None, 'ed1f3e5f4da1f5895620d6887b933a494928592014144f1fdbe6633ff05fe2d9'], 'content': '"""実運用5件で報告された外部サイト採用・治療誤検出の回帰テスト。外部通信は行わない。"""\nimport json\nimport pytest\nfrom src.enrichment.hp_analysis import Page,identity,is_official_candidate\nfrom src.enrichment.researcher import Researcher\nfrom src.enrichment.search_provider import CachedSearch,SearchError\nfrom src.master.filters import Filters\nfrom src.master.jobs import create_job,run_job,job_status,job_limit\nfrom src.master.samples import sample_records\nfrom src.master.store import ClinicStore\nfrom src.scoring.research_scoring import treatments,hp_signals,rank_hp,signal\n\n\n@pytest.fixture\ndef store(tmp_path):\n    return ClinicStore(tmp_path/"clinics.db")\n\n\ndef clinic_page(record,url,content=""):\n    return Page(url,f\'<title>{record["clinic_name"]}</title><h1>{record["clinic_name"]}</h1>\'\n                f\'<p>{record["phone"]} {record["address"]}</p>{content}\')\n\n\nclass Provider:\n    def __init__(self,batches=()):\n        self.batches=list(batches)\n        self.queries=[]\n\n    def search(self,query):\n        self.queries.append(query)\n        return self.batches[len(self.queries)-1] if len(self.queries)<=len(self.batches) else []\n\n\nclass Fetcher:\n    def __init__(self,pages):\n        self.pages=pages\n        self.calls=[]\n\n    def fetch(self,url,allowed_host=None):\n        self.calls.append(url)\n        return self.pages[url]\n\n\n@pytest.mark.parametrize("url",[\n    "https://job-medley.com/facility/345406/",\n    "https://www.senshin-daido-life.jp/search/hospital/1314122859",\n    "https://fdoc.jp/clinic/detail/index/id/160861/",\n    "https://gmo-clinic-map.com/hospital/ref/mt25r4wjl",\n    "https://www.web-clover.net/cgi-bin/disp.cgi?itky22110=",\n])\ndef test_external_listing_identity_does_not_mean_clinic_website(url):\n    record=sample_records()[0]\n    page=clinic_page(record,url,\'<h2>内視鏡</h2><p>内視鏡検査。</p>\'\n        \'<a href="https://youtube.com/@jobmedley">運営会社公式YouTube</a>\'\n        \'<a href="https://tiktok.com/@jobmedley">運営会社公式TikTok</a>\')\n    assert identity(record,page,official=False)["verified"]\n    assert not is_official_candidate(url)\n    assert not identity(record,page)["verified"]\n    assert treatments([page])["treatment_categories"]==[]\n    assert hp_signals(record,[page])==[]\n    assert rank_hp([page],{},[])["hp_rank"]=="NO_HP"\n\n\ndef test_ophthalmic_laser_is_not_dermatology():\n    record=sample_records()[0]\n    page=clinic_page(record,"https://eye.example/",\n        \'<h2>緑内障レーザー治療</h2><p>緑内障レーザー治療を行います。</p>\'\n        \'<h2>レーザー治療</h2><p>眼科のレーザー治療について。</p>\')\n    result=treatments([page])\n    assert "緑内障" in result["treatment_categories"]\n    assert "皮膚科" not in result["treatment_categories"]\n    skin=clinic_page(record,"https://skin.example/",\'<h2>シミ治療</h2><p>シミ治療に対応します。</p>\')\n    assert "皮膚科" in treatments([skin])["treatment_categories"]\n\n\ndef test_own_clinic_sns_and_shared_web_host_still_work():\n    record=sample_records()[0]\n    page=clinic_page(record,"https://www5a.biglobe.ne.jp/~gannka/",\n        \'<a href="https://youtube.com/@clinic">当院のYouTube</a>\'\n        \'<a href="https://tiktok.com/@clinic">当院のTikTok</a>\')\n    assert identity(record,page)["verified"]\n    assert {s["name"] for s in hp_signals(record,[page])}=={"YouTube公式運用","TikTok公式運用"}\n\n\n@pytest.mark.parametrize("bad_url",[\n    "https://job-medley.com/facility/345406/",\n    "https://www.senshin-daido-life.jp/search/hospital/1314122859",\n])\ndef test_previous_wrong_hp_and_first_search_listing_are_skipped(store,bad_url):\n    record={**sample_records()[0],"hp_url":bad_url}\n    url="https://correct-clinic.example/"\n    provider=Provider([[{"url":bad_url},{"url":url}]])\n    fetcher=Fetcher({url:clinic_page(record,url)})\n    result,_=Researcher(CachedSearch(store,provider),fetcher).hp(record,force=True)\n    assert result["hp_url"]==url and result["hp_verified"]\n    assert fetcher.calls==[url] and len(provider.queries)==1\n    assert result["marketing_signals"]==[]\n\n\ndef test_external_only_results_use_one_name_address_fallback(store):\n    record={**sample_records()[0],"clinic_name":"医療法人社団 佳翔会 武蔵小金井さくら眼科"}\n    url="https://sakuraganka.jp/"\n    provider=Provider([[{"url":"https://job-medley.com/facility/1/"}],[{"url":url}]])\n    fetcher=Fetcher({url:clinic_page(record,url)})\n    result,_=Researcher(CachedSearch(store,provider),fetcher).hp(record)\n    assert result["hp_url"]==url and result["hp_status"]=="VERIFIED"\n    assert len(provider.queries)==2\n    assert \'"武蔵小金井さくら眼科"\' in provider.queries[1]\n    assert "佳翔会" not in provider.queries[1]\n    assert record["address"] in provider.queries[1]\n    assert "公式ホームページ" in provider.queries[1]\n\n\ndef test_redirect_to_listing_is_not_crawled_or_scored(store):\n    record=sample_records()[0]\n    url="https://old-clinic.example/"\n    listing="https://job-medley.com/facility/1/"\n    provider=Provider([[{"url":url}],[]])\n    fetcher=Fetcher({url:clinic_page(record,listing,\'<a href="/about/">医院概要</a>\')})\n    result,pages=Researcher(CachedSearch(store,provider),fetcher).hp(record)\n    assert result["hp_status"]=="REVIEW" and not result["hp_verified"]\n    assert pages==[] and result["marketing_signals"]==[] and fetcher.calls==[url]\n\n\ndef seed_incorrect_result(store):\n    record=sample_records()[0]\n    store.import_master([record])\n    cid=store.query(Filters(hp_only=False))[0]["id"]\n    store.save_research(cid,{"hp_status":"VERIFIED","hp_url":"https://job-medley.com/facility/1/",\n        "hp_rank":"A","hp_score":100,"hp_rank_reasons":[{"feature":"誤ったSNS","points":100}],\n        "treatment_categories":["皮膚科"],"treatment_evidence":[{"category":"皮膚科"}],\n        "treatment_confidence":{"皮膚科":.9},"hp_identity_pages":["https://job-medley.com/facility/1/"],\n        "marketing_signals":[signal("YouTube公式運用","https://job-medley.com/facility/1/","公式HPのチャンネルリンク","求人サイト自身のSNS")],\n        "epark_url":"https://epark.jp/shopinfo/hpl123/","epark_status":"VERIFIED","epark_contract":"FREE"},\n        [{"url":"https://job-medley.com/facility/1/","text":"旧ページ"}])\n    return cid\n\n\n@pytest.mark.parametrize("fail",[False,True])\ndef test_rerun_clears_untrusted_old_analysis_and_keeps_sources_history_epark(store,fail):\n    cid=seed_incorrect_result(store)\n    with store.connect() as c:\n        before_sources=[tuple(row) for row in c.execute("SELECT * FROM source_records")]\n        previous=c.execute("SELECT result_json FROM research_results WHERE clinic_id=?",(cid,)).fetchone()[0]\n    class Search(Provider):\n        def search(self,query):\n            if fail:\n                raise SearchError("Tavily接続エラー")\n            return super().search(query)\n    jid=create_job(store,Filters(hp_only=False),force=True,max_searches=10)\n    run_job(store,jid,Search(),Fetcher({}))\n    current=store.get(cid)\n    assert current["hp_status"]==("ERROR" if fail else "NOT_FOUND")\n    assert current["hp_url"]=="" and current["hp_score"]==0\n    assert current["hp_rank_reasons"]==[] and current["hp_identity_pages"]==[]\n    assert current["treatment_categories"]==[] and current["treatment_evidence"]==[]\n    assert current["treatment_confidence"]=={} and current["marketing_signal_count"]==0\n    assert current["epark_url"]=="https://epark.jp/shopinfo/hpl123/"\n    assert current["epark_contract"]=="FREE"\n    with store.connect() as c:\n        assert [tuple(row) for row in c.execute("SELECT * FROM source_records")]==before_sources\n        assert c.execute("SELECT count(*) FROM hp_pages WHERE clinic_id=?",(cid,)).fetchone()[0]==0\n        assert previous in [row[0] for row in c.execute("SELECT before_json FROM change_history WHERE clinic_id=?",(cid,))]\n\n\ndef test_manual_corrections_survive_rerun(store):\n    cid=seed_incorrect_result(store)\n    store.override(cid,"treatment_categories",["白内障"],note="目視確認済み")\n    jid=create_job(store,Filters(hp_only=False),force=True,max_searches=10)\n    run_job(store,jid,Provider(),Fetcher({}))\n    assert store.get(cid)["treatment_categories"]==["白内障"]\n    with store.connect() as c:\n        auto=json.loads(c.execute("SELECT result_json FROM research_results WHERE clinic_id=?",(cid,)).fetchone()[0])\n    assert auto["treatment_categories"]==[]\n\n\n@pytest.mark.parametrize("outcome",["success","not_found","error"])\ndef test_independently_verified_media_survives_hp_rerun(store,outcome):\n    cid=seed_incorrect_result(store)\n    current=store.get(cid)\n    store.save_research(cid,{"marketing_signals":current["marketing_signals"]+[\n        signal("Doctors File掲載","https://doctorsfile.jp/h/1/","検索結果の医院名・電話/住所一致","独立した媒体調査で確認") ]})\n    url="https://official.example/"\n    class Search(Provider):\n        def search(self,query):\n            if outcome=="error":\n                raise SearchError("Tavily接続エラー")\n            return [{"url":url}] if outcome=="success" else []\n    jid=create_job(store,Filters(hp_only=False),force=True,max_searches=10)\n    run_job(store,jid,Search(),Fetcher({url:clinic_page(current,url)}))\n    assert [s["name"] for s in store.get(cid)["marketing_signals"]]==["Doctors File掲載"]\n    assert store.get(cid)["marketing_signal_count"]==1\n\n\ndef test_fallback_budget_pause_reuses_first_search_on_resume(store):\n    store.import_master(sample_records()[:1])\n    record=store.query(Filters(hp_only=False))[0]\n    url="https://official.example/"\n    provider=Provider([[],[{"url":url}]])\n    fetcher=Fetcher({url:clinic_page(record,url)})\n    jid=create_job(store,Filters(hp_only=False),force=True,max_searches=1)\n    run_job(store,jid,provider,fetcher)\n    assert job_status(store,jid)["status"]=="BUDGET" and len(provider.queries)==1\n    job_limit(store,jid,2)\n    run_job(store,jid,provider,fetcher)\n    assert job_status(store,jid)["status"]=="COMPLETED" and len(provider.queries)==2\n    assert store.get(record["id"])["hp_url"]==url\n'},
    'docs/HP_RESEARCH_FIX.md': {'before_sha256s': [None, '4551f64fe8ce95a8e1977299dc6af5ec5db5b63a76dc4055fb456c3a22e9df36'], 'content': '# HP調査の誤判定修正（2026-09-14）\n\n## 対象となった不具合\n\n- アイクリニック東京 サピアタワーで求人サイトを公式HPと判定し、そのサイト自身のSNSや他科の情報を取り込んだ。\n- 武蔵小金井さくら眼科で大同生命の医療機関検索ページを公式HPと判定した。\n- 眼科の「レーザー治療」を皮膚科の根拠に使った。\n- 再調査で公式HPを確認できなくなっても、前回の治療カテゴリなどが現行結果に残った。\n\n## 修正内容\n\n1. 上記の求人・医療機関検索サイト、および確認した関連検索サイトを公式HP候補から除外する。移転先が該当サイトの場合も公式HPとして採用しない。\n2. 除外したページからHPランク・治療カテゴリ・HP上のSNSシグナルを算出しない。\n3. 汎用語「レーザー治療」を皮膚科キーワードから外す。緑内障レーザー治療、ニキビ・シミ治療などの具体的な判定は継続する。\n4. 正式名・電話番号で公式HPを確認できなかった場合だけ、法人名を除いた医院名と所在地で1回補完検索する。Tavilyは1医院最大2回、従来の月間・調査上限と再開キャッシュを使用する。候補の本人確認条件は変更しない。\n5. HP再調査で未発見・要確認・エラーとなった場合、旧HP由来の自動判定と現行の取得ページを消去する。過去の調査履歴、元CSV・UUID、手動修正、EPARK、独立して確認した外部媒体のシグナルは保持する。\n\n## Windowsでの適用\n\n1. アプリを起動した黒い画面で Ctrl+C を押して停止する。\n2. `update_hp_research_fix.py` を、使用中の `app_v2.py` と同じフォルダーに置く。\n3. そのフォルダーをエクスプローラーで開き、アドレス欄に `cmd` と入力して Enter。\n4. 次を1回実行する。\n\n```bat\npy -3 update_hp_research_fix.py\n```\n\n更新成功を確認してから起動する。\n\n```bat\n.\\.venv\\Scripts\\python.exe scripts\\launch_v2.py\n```\n\n更新プログラムは変更前のコードを `code_backup_hp_research_*` に保存する。想定外のコード変更がある場合は上書きせず停止する。データベースは更新時には変更しない。\n\n## 5件の再調査\n\n「サンプルモード」をオフにし、「自動情報収集」で以下を指定する。\n\n| 項目 | 設定 |\n|---|---|\n| 現存クリニックのみ | オン |\n| HP確認済みのみ | オフ |\n| 既存UUID | あり |\n| 都道府県 | 東京都 |\n| その他の絞り込み | 未選択・指定なし・オフ |\n| 調査内容 | 公式HPの発見・内容調査 |\n| 今回の医院数 | 5 |\n| 今回の検索上限 | 10 |\n| 1医院の最大HPページ数 | 20 |\n| 強制再調査 | オン |\n\nTavilyキーをアプリの入力欄に入れ、「自動調査を開始」を1回押す。今回は完了済み5件の再検証なので、強制再調査をオンにする。以前の完了済みジョブを再開する操作ではない。\n\n再統合・CSVの再アップロードは不要。更新ファイルの実行だけでは、過去の誤った調査表示は変わらない。再調査で置き換わる。\n\n## 確認できた公式URL（閲覧時点）\n\n- アイクリニック東京 サピアタワー: https://eyeclinic-tokyo.jp/clinic/sapiatower/\n- 武蔵小金井さくら眼科: https://sakuraganka.jp/\n\n上記URLをコードやDBに固定登録してはいない。自動検索で見つけた候補が本人確認条件を満たさなければ「要確認」にする。\n\n## 検証の範囲\n\nLinux・Python 3.12の自動テスト222件で確認。求人サイトの除外、眼科レーザーの分類、再調査時の古い結果の除去、元レコード・手動修正・独立した媒体情報・EPARK・履歴の保持、検索上限での停止と再開を含む。検索と取得はテスト用応答を使用する。\n\n公開HPの内容は閲覧確認したが、Tavilyの実APIキーは検証環境にない。Windows実機および利用者の保存DBでの実調査は、上記の手順で確認する。\n'},
    'src/enrichment/consultation_schedule.py': {'before_sha256s': [None], 'content': '"""通常の午前・午後診療の間に明記された検査・手術枠を、HTMLの同一時間表から確認。"""\nfrom dataclasses import dataclass\nimport re\nimport unicodedata\nfrom bs4 import BeautifulSoup\n\nSIGNAL_NAME = "昼の検査・手術専用枠"\nWEEKDAYS = "月火水木金土日"\nPROCEDURE = re.compile(r"検査|手術|内視鏡|胃カメラ|大腸カメラ")\nORDINARY = re.compile(r"午前|午後|外来|診察|診療|受付時間")\nNEGATIVE = re.compile(r"行っていません|行っておりません|行いません|行わない|実施していません|実施しておりません|実施しません|対応していません|実施なし|休止|中止|検討中|予定|予約受付|予約の受付|相談|説明|(?:検査|手術|内視鏡)(?:は)?(?:なし|無し|休み|休診)")\nRANGE = re.compile(\n    r"(?P<p1>午前|午後|AM|PM)?\\s*(?P<h1>\\d{1,2})\\s*(?::\\s*(?P<m1>\\d{2})|時(?:(?P<j1>\\d{1,2})分)?)"\n    r"\\s*(?:[~〜～\\-−‐‑–—―]|から)\\s*"\n    r"(?P<p2>午前|午後|AM|PM)?\\s*(?P<h2>\\d{1,2})\\s*(?::\\s*(?P<m2>\\d{2})|時(?:(?P<j2>\\d{1,2})分)?)",\n    re.I,\n)\n\n\ndef clean(text):\n    return unicodedata.normalize("NFKC",str(text or "")).strip()\n\n\ndef days(text):\n    text=clean(text)\n    result=set()\n    if "平日" in text:\n        result.update(range(5))\n    for match in re.finditer(r"([月火水木金土日])(?:曜日?)?\\s*[~〜～-]\\s*([月火水木金土日])(?:曜日?)?",text):\n        start,end=(WEEKDAYS.index(x) for x in match.groups())\n        if start<=end:\n            result.update(range(start,end+1))\n    for match in re.finditer(r"([月火水木金土日])曜日?",text):\n        result.add(WEEKDAYS.index(match[1]))\n    if re.fullmatch(r"[月火水木金土日\\s・、,/／]+",text):\n        result.update(WEEKDAYS.index(x) for x in text if x in WEEKDAYS)\n    return frozenset(result) if result else None\n\n\ndef kind(label,default=""):\n    label=clean(label)\n    if NEGATIVE.search(label):\n        return ""\n    if PROCEDURE.search(label):\n        # 一般診療と並行する検査は、独立した専用枠としない。\n        without_closure=re.sub(r"(?:一般)?(?:外来|診療|診察)(?:は)?(?:休診|なし|を休止|を行わない)","",label)\n        if re.search(r"外来|診療|診察",without_closure):\n            return ""\n        return "procedure"\n    if re.search(r"休診|休憩|昼休|受付のみ|予約のみ",label):\n        return ""\n    return "ordinary" if ORDINARY.search(label) else default\n\n\n@dataclass(frozen=True)\nclass Slot:\n    start: int\n    end: int\n    kind: str\n    days: frozenset | None\n    text: str\n\n\ndef slots(text,default="",day_set=None):\n    text=clean(text)\n    matches=list(RANGE.finditer(text))\n    previous=0\n    inherited=default\n    found=[]\n    for match in matches:\n        prefix=text[previous:match.start()]\n        label=text if len(matches)==1 else prefix\n        role=kind(label,inherited)\n        period1=(match[\'p1\'] or ("午後" if "午後" in prefix else "午前" if "午前" in prefix else "")).upper()\n        period2=(match[\'p2\'] or period1).upper()\n        values=[]\n        for number,period in [(1,period1),(2,period2)]:\n            hour=int(match[f\'h{number}\'])\n            minute=int(match[f\'m{number}\'] or match[f\'j{number}\'] or 0)\n            if period in {"午後","PM"} and hour<12:\n                hour+=12\n            elif (period=="AM" or (period=="午前" and number==1)) and hour==12:\n                hour=0\n            values.append(hour*60+minute if hour<=24 and minute<60 and (hour<24 or minute==0) else -1)\n        start,end=values\n        if role and 0<=start<end<=24*60:\n            found.append(Slot(start,end,role,day_set if day_set is not None else days(label),label[:300]))\n        previous=match.end()\n        inherited=role\n    return found\n\n\ndef grid(table):\n    rows=[r for r in table.find_all(\'tr\') if r.find_parent(\'table\') is table]\n    if len(rows)>80:\n        return []\n    cells={}\n    width=0\n    for y,row in enumerate(rows):\n        x=0\n        for cell in row.find_all([\'th\',\'td\'],recursive=False):\n            while (y,x) in cells:\n                x+=1\n            try:\n                colspan=max(1,int(cell.get(\'colspan\',1)))\n                rowspan=max(1,int(cell.get(\'rowspan\',1)))\n            except (TypeError,ValueError):\n                return []\n            if x+colspan>24 or rowspan>80:\n                return []\n            for yy in range(y,min(len(rows),y+rowspan)):\n                for xx in range(x,x+colspan):\n                    cells[yy,xx]=clean(cell.get_text(\' \',strip=True))\n            x+=colspan\n            width=max(width,x)\n    return [[cells.get((y,x),\'\') for x in range(width)] for y in range(len(rows))]\n\n\ndef table_slots(table):\n    matrix=grid(table)\n    if not matrix:\n        return []\n    # 曜日が横に並ぶ一般的な診療時間表。異なる曜日の枠を混ぜない。\n    header=next(((i,{j:days(cell) for j,cell in enumerate(row) if days(cell)})\n                 for i,row in enumerate(matrix) if sum(days(cell) is not None for cell in row)>=2),None)\n    found=[]\n    if header:\n        row_index,columns=header\n        first_day=min(columns)\n        for row in matrix[row_index+1:]:\n            prefix=\' \'.join(row[:first_day])\n            for column,day_set in columns.items():\n                cell=row[column]\n                # 曖昧な記号・脚注は、通常診療や専用枠と推測しない。\n                if not RANGE.search(cell) and not re.fullmatch(r"[○◯〇●◎]+",cell) and not ORDINARY.search(cell) and not PROCEDURE.search(cell):\n                    continue\n                if not PROCEDURE.search(cell) and re.search(r"休診|休み|なし",cell):\n                    continue\n                selected_days=day_set & days(prefix) if days(prefix) else day_set\n                if not selected_days:\n                    continue\n                text=prefix+\' \'+cell\n                found.extend(slots(text,default=\'ordinary\',day_set=selected_days))\n        return found\n    # 曜日が縦に並ぶ表、または「午前／検査・手術／午後」の簡単な表。\n    schedule=bool(re.search(r"診療|外来|午前|午後",table.get_text(\' \',strip=True)))\n    headings=matrix[0]\n    for row in matrix:\n        row_days=days(row[0])\n        if row_days:\n            for column,cell in enumerate(row[1:],1):\n                found.extend(slots(headings[column]+\' \'+cell,default=\'ordinary\' if schedule else \'\',day_set=row_days))\n        else:\n            found.extend(slots(\' \'.join(row),default=\'ordinary\' if schedule else \'\'))\n    return found\n\n\ndef proof(found):\n    for day in range(7):\n        same_day=[s for s in found if s.days is None or day in s.days]\n        for procedure in same_day:\n            if procedure.kind!=\'procedure\':\n                continue\n            morning=[s for s in same_day if s.kind==\'ordinary\' and s.start<12*60 and s.end<=procedure.start]\n            afternoon=[s for s in same_day if s.kind==\'ordinary\' and s.start>=12*60 and procedure.end<=s.start]\n            if not morning or not afternoon:\n                continue\n            before=max(morning,key=lambda s:s.end)\n            after=min(afternoon,key=lambda s:s.start)\n            def fmt(slot):\n                return f\'{slot.start//60:02}:{slot.start%60:02}～{slot.end//60:02}:{slot.end%60:02}\'\n            label=WEEKDAYS[day]+\'曜\' if any(s.days is not None for s in [before,procedure,after]) else \'共通時間表\'\n            return {\'schedule_day\':label,\'morning_consultation\':fmt(before),\'procedure_slot\':fmt(procedure),\n                    \'afternoon_consultation\':fmt(after),\n                    \'evidence\':f\'{label}：午前診療 {fmt(before)}／検査・手術 {fmt(procedure)}／午後診療 {fmt(after)}\',\n                    \'source_excerpt\':procedure.text}\n    return None\n\n\ndef midday_procedure(html):\n    """明示された3枠を同一の表・本文ブロックで確認できたときだけ根拠を返す。"""\n    soup=BeautifulSoup(html,\'html.parser\')\n    for node in soup.select(\'script,style,noscript,template\'):\n        node.decompose()\n    for table in soup.find_all(\'table\'):\n        if table.find(\'table\') is not None:\n            continue\n        result=proof(table_slots(table))\n        if result:\n            return {**result,\'evidence_type\':\'公式HPの診療時間表で前後の通常診療と専用枠を確認\'}\n    # 文字の診療時間案内にも対応。別の医院・見出し・表の時間帯は合成しない。\n    for table in soup.find_all(\'table\'):\n        table.decompose()\n    for br in soup.find_all(\'br\'):\n        br.replace_with(\'\\n\')\n    groups={}\n    for node in soup.find_all([\'p\',\'li\',\'dd\',\'div\']):\n        if node.find([\'p\',\'li\',\'dd\',\'div\',\'table\']) is not None:\n            continue\n        if node.find_parent([\'p\',\'li\',\'dd\']) is not None:\n            continue\n        heading=node.find_previous([\'h1\',\'h2\',\'h3\',\'h4\',\'h5\',\'h6\'])\n        container=node.find_parent([\'section\',\'article\',\'div\',\'main\',\'body\']) or soup\n        key=(id(container),id(heading))\n        default=\'ordinary\' if heading and re.search(r"診療時間|外来時間",heading.get_text()) else \'\'\n        label=\'\'\n        if node.name==\'dd\':\n            term=node.find_previous_sibling(\'dt\')\n            label=term.get_text(\' \',strip=True) if term else \'\'\n        for line in node.get_text(\' \').splitlines():\n            if len(line)<=1200:\n                groups.setdefault(key,[]).extend(slots(label+\' \'+line,default=default))\n    for found in groups.values():\n        result=proof(found)\n        if result:\n            return {**result,\'evidence_type\':\'公式HPの診療時間案内で前後の通常診療と専用枠を確認\'}\n    return None\n'},
    'tests/test_midday_procedure_signal.py': {'before_sha256s': [None], 'content': '"""昼の専用枠の判定境界と、既存の加点・保存・絞り込みへの接続を確認。"""\nimport pytest\nimport unicodedata\nfrom src.enrichment.consultation_schedule import midday_procedure,SIGNAL_NAME\nfrom src.enrichment.hp_analysis import Page\nfrom src.enrichment.researcher import Researcher\nfrom src.master.filters import Filters\nfrom src.master.samples import sample_records\nfrom src.master.store import ClinicStore\nfrom src.scoring.research_scoring import hp_signals,finalize_result,signal\n\n\ndef simple_table(procedure=\'検査・手術\',start=\'12:00\',end=\'15:00\',morning_end=\'12:00\',afternoon_start=\'15:00\'):\n    return f\'\'\'<table><caption>診療時間</caption>\n      <tr><th>午前診療</th><td>9:00～{morning_end}</td></tr>\n      <tr><th>{procedure}</th><td>{start}～{end}</td></tr>\n      <tr><th>午後診療</th><td>{afternoon_start}～18:00</td></tr></table>\'\'\'\n\n\ndef page(html,url=\'https://clinic.example/\'):\n    r=sample_records()[0]\n    return Page(url,f\'<title>{r["clinic_name"]}</title><h1>{r["clinic_name"]}</h1><p>{r["phone"]}</p>\'+html)\n\n\n@pytest.mark.parametrize(\'label\',[\'検査・手術\',\'内視鏡検査（予約制）\',\'手術専用\',\'大腸カメラ\',\'外来休診・検査専用\'])\ndef test_dedicated_procedure_between_two_consultations(label):\n    result=midday_procedure(simple_table(label))\n    assert result is not None\n    assert result[\'morning_consultation\']==\'09:00～12:00\'\n    assert result[\'procedure_slot\']==\'12:00～15:00\'\n    assert result[\'afternoon_consultation\']==\'15:00～18:00\'\n    assert unicodedata.normalize(\'NFKC\',label) in result[\'source_excerpt\']\n\n\n@pytest.mark.parametrize(\'label\',[\'昼休み\',\'検査予約受付\',\'手術の相談\',\'検査は行っていません\',\'検査実施なし\',\'検査は休止\',\'手術予定\',\'一般診療・検査\',\'通常外来と手術\',\'手術は行っておりません\',\'検査は実施しておりません\',\'検査・手術なし\',\'検査の説明\'])\ndef test_break_negation_reservations_and_parallel_care_not_dedicated(label):\n    assert midday_procedure(simple_table(label)) is None\n\n\n@pytest.mark.parametrize(\'start,end\',[(\'11:00\',\'14:00\'),(\'14:00\',\'16:00\'),(\'18:00\',\'19:00\'),(\'13:00\',\'13:00\'),(\'25:00\',\'26:00\')])\ndef test_overlapping_after_hours_or_invalid_interval_not_midday(start,end):\n    assert midday_procedure(simple_table(start=start,end=end)) is None\n\n\ndef test_gap_can_include_breaks_around_the_procedure():\n    result=midday_procedure(simple_table(start=\'13:00\',end=\'14:00\',afternoon_start=\'15:30\'))\n    assert result[\'procedure_slot\']==\'13:00～14:00\'\n\n\ndef test_procedure_only_in_afternoon_without_later_consultation_not_counted():\n    html=\'<table><tr><th>午前診療</th><td>9:00～12:00</td></tr><tr><th>午後手術</th><td>13:00～18:00</td></tr></table>\'\n    assert midday_procedure(html) is None\n\n\ndef test_days_across_columns_must_intersect():\n    html=\'\'\'<table><tr><th>診療時間</th><th>月</th><th>火</th></tr>\n    <tr><th>9:00～12:00</th><td>●</td><td>●</td></tr>\n    <tr><th>12:00～15:00</th><td>検査・手術</td><td>休診</td></tr>\n    <tr><th>15:00～18:00</th><td>休診</td><td>●</td></tr></table>\'\'\'\n    assert midday_procedure(html) is None\n    html=html.replace(\'<td>休診</td><td>●</td>\',\'<td>●</td><td>●</td>\')\n    assert midday_procedure(html)[\'schedule_day\']==\'月曜\'\n\n\ndef test_weekday_row_layout():\n    html=\'\'\'<table><tr><th>曜日</th><th>午前診療</th><th>検査・手術</th><th>午後診療</th></tr>\n    <tr><th>火曜日</th><td>9:00～12:00</td><td>13:00～15:00</td><td>15:30～18:00</td></tr></table>\'\'\'\n    assert midday_procedure(html)[\'schedule_day\']==\'火曜\'\n\n\ndef test_merged_cells_keep_the_same_days():\n    html=\'\'\'<table><tr><th>診療時間</th><th>月</th><th>火</th><th>水</th></tr>\n    <tr><th>9:00～12:00</th><td>●</td><td>●</td><td>休診</td></tr>\n    <tr><th>12:00～15:00</th><td colspan="2">検査・手術</td><td>休診</td></tr>\n    <tr><th>15:00～18:00</th><td>●</td><td>●</td><td>休診</td></tr></table>\'\'\'\n    assert midday_procedure(html)[\'procedure_slot\']==\'12:00～15:00\'\n\n\ndef test_unexplained_symbol_not_surgery():\n    html=\'\'\'<table><tr><th>診療時間</th><th>月</th><th>火</th></tr>\n    <tr><th>9:00～12:00</th><td>●</td><td>●</td></tr>\n    <tr><th>12:00～15:00</th><td>★</td><td>★</td></tr>\n    <tr><th>15:00～18:00</th><td>●</td><td>●</td></tr></table>\'\'\'\n    assert midday_procedure(html) is None\n\n\n@pytest.mark.parametrize(\'html\',[\n    \'<section><h2>診療時間</h2><p>午前診療 9:00～12:00</p><p>検査・手術 13:00～15:00</p><p>午後診療 15:00～18:00</p></section>\',\n    \'<div>午前診療 <span>９：００</span>～１２：００<br>検査・手術 １３：００～１５：００<br>午後診療 １５：００～１８：００</div>\',\n    \'<section><h2>診療時間</h2><p>午前診療 9:00～12:00 / 検査・手術 13:00～15:00 / 午後診療 15:00～18:00</p></section>\',\n    \'<dl><dt>午前診療</dt><dd>9時～12時</dd><dt>検査・手術</dt><dd>13時～15時</dd><dt>午後診療</dt><dd>午後3時～6時</dd></dl>\',\n])\ndef test_text_schedule_and_fullwidth_times(html):\n    result=midday_procedure(html)\n    assert result and result[\'procedure_slot\']==\'13:00～15:00\'\n\n\ndef test_text_different_days_or_sections_not_combined():\n    html=\'<section><p>月曜 午前診療 9:00～12:00</p><p>火曜 検査・手術 13:00～15:00</p><p>月曜 午後診療 15:00～18:00</p></section>\'\n    assert midday_procedure(html) is None\n    html=\'<section><h2>A院</h2><p>午前診療 9:00～12:00</p><p>検査・手術 13:00～15:00</p><h2>B院</h2><p>午後診療 15:00～18:00</p></section>\'\n    assert midday_procedure(html) is None\n\n\ndef test_images_and_generic_surgery_mention_do_not_add_point():\n    html=\'<h2>日帰り手術に対応</h2><img src="hours.png" alt="診療時間">\'\n    assert midday_procedure(html) is None\n    html=\'<section><p>午前診療 9:00～12:00</p><p>昼休みは検査と手術を行います。</p><p>午後診療 15:00～18:00</p></section>\'\n    assert midday_procedure(html) is None\n\n\ndef test_point_is_once_per_clinic_and_requires_two_for_hot():\n    p=page(simple_table())\n    signals=hp_signals(sample_records()[0],[p,p])\n    assert [s[\'name\'] for s in signals]==[SIGNAL_NAME]\n    assert signals[0][\'evidence_url\']==p.url\n    assert \'12:00～15:00\' in signals[0][\'evidence\']\n    result=finalize_result({\'marketing_signals\':signals})\n    assert result[\'marketing_signal_count\']==1 and result[\'hot_status\']==\'集客投資シグナルあり\'\n    result=finalize_result({\'marketing_signals\':signals+[signal(\'YouTube公式運用\',p.url,\'test\',\'公式チャンネル\')]})\n    assert result[\'marketing_signal_count\']==2 and result[\'hot_status\']==\'アツい\'\n\n\ndef test_nonofficial_directory_cannot_add_schedule_point():\n    assert hp_signals(sample_records()[0],[page(simple_table(),url=\'https://job-medley.com/facility/1/\')])==[]\n\n\ndef test_hp_research_storage_and_filter_without_new_search(tmp_path):\n    store=ClinicStore(tmp_path/\'clinics.db\')\n    store.import_master(sample_records()[:1])\n    record=store.query(Filters(hp_only=False))[0]\n    class Search:\n        def search(self,*args,**kwargs):\n            raise AssertionError(\'This feature must not add a search for a known HP\')\n    class Fetcher:\n        def fetch(self,url,allowed_host=None):\n            return page(simple_table(),url=url)\n    result,pages=Researcher(Search(),Fetcher()).hp({**record,\'hp_url\':\'https://clinic.example/\'})\n    store.save_research(record[\'id\'],result,pages)\n    selected=store.query(Filters(hp_only=True,signals=[SIGNAL_NAME]))\n    assert len(selected)==1 and selected[0][\'marketing_signal_count\']==1\n    assert selected[0][\'hot_status\']==\'集客投資シグナルあり\'\n    store.override(record[\'id\'],\'marketing_signals\',[SIGNAL_NAME,\'YouTube公式運用\'],note=\'目視確認\')\n    assert store.get(record[\'id\'])[\'hot_status\']==\'アツい\'\n'},
    'docs/MIDDAY_PROCEDURE_SIGNAL.md': {'before_sha256s': [None], 'content': '# 昼の検査・手術専用枠の加点（2026-09-15）\n\n医院のHPに「通常の午前診療と午後診療の間に、検査・手術の専用枠を設けている」と分かる時間表がある場合、集客投資シグナルに「昼の検査・手術専用枠」を追加する。\n\n## 判定例\n\n| 時間 | 内容 |\n|---|---|\n| 9:00～12:00 | 午前診療 |\n| 13:00～15:00 | 検査・手術専用 |\n| 15:00～18:00 | 午後診療 |\n\nこの例は1点。YouTube公式運用など別のシグナルがもう1つあれば、合計2点で「アツい」。複数曜日・複数ページで同じ専用枠を見つけても、この項目は1点のみ。\n\n## 自動判定する条件\n\n- 本人確認を通過したHPの調査で取得した、文字の時間案内またはHTML表を利用する。\n- 同じ時間表・同じ曜日に午前の通常診療、検査・手術枠、午後の通常診療の3つを確認する。\n- 午前診療の終了後に専用枠が始まり、その終了後に午後診療が始まる。\n- 内視鏡検査、胃カメラ、大腸カメラなどの専用枠も含める。\n- 空白の休憩時間が前後にあっても、専用枠が通常診療の間に収まれば対象。\n\n「検査・手術に対応」とだけある場合、専用枠の開始・終了が不明な場合、通常診療と重なる場合、午後が手術のみでその後の通常診療がない場合は、自動加点しない。休止・実施なし・予約受付・相談だけの枠も対象外。\n\n画像・PDFのみの時間表や意味を確認できない記号・脚注は、自動で推測しない。現時点ではOCRを追加していない。目視で確認できた場合は、医院詳細の手動修正から「集客投資シグナル」を選び、この項目を追加できる。変更理由に時間帯・曜日を記入する。\n\n## 画面と保存\n\n- 「シグナル一覧」に表示され、既存のシグナル数・アツさに反映される。\n- 「必須の集客投資シグナル（選んだものすべて）」で、この条件の医院を絞り込める。\n- 詳細に根拠URL、午前・専用枠・午後の時間帯、曜日、根拠文を保存する。\n- HPランク・年齢推定の基準、コムデスクA～ABの28列、既存UUID・元データの仕様は変更しない。\n- 通常のHP調査で取得した内容を使い、この判定専用のTavily検索は追加しない。\n\n## Windows更新\n\n今回のアップデータは前回のHP誤判定修正も含む。前回修正の適用前・適用後の両方に対応する。対応外のコード変更がある場合は上書きせず停止する。\n\n1. 起動した黒い画面で Ctrl+C を押してアプリを停止する。\n2. `update_midday_procedure_signal.py` を、使用中の `app_v2.py` と同じフォルダーに置く。\n3. そのフォルダーのエクスプローラーのアドレス欄に `cmd` と入力して Enter。\n4. 次を1回実行する。\n\n```bat\npy -3 update_midday_procedure_signal.py\n```\n\n成功したら起動する。\n\n```bat\n.\\.venv\\Scripts\\python.exe scripts\\launch_v2.py\n```\n\n保存済みの医院へ自動判定を反映するには、「自動情報収集」で公式HPの発見・内容調査を選び、対象医院の「強制再調査」をオンにして開始する。まずは東京都・既存UUIDあり・現存クリニックのみオン・HP確認済みのみオフ・5医院・検索上限10・最大20ページで確認する。CSVの再取り込み・再統合は不要。\n\n## 検証\n\n自動テスト260件に成功。通常枠との重複、異なる曜日の取り違え、休診・休止、時間不足、画像だけの表示、全角表記、結合セル、重複加点、1点／2点の判定、保存と絞り込みを含む。Linux・Python 3.12でテスト用HTMLを使用。Windows実機と実医院の時間表による確認は別途必要。\n'},
}



def normalized(path):
    return path.read_text(encoding="utf-8-sig").replace("\r\n", "\n")


def atomic_write(path, content):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", newline="\n", dir=path.parent, delete=False) as handle:
            temporary = Path(handle.name)
            handle.write(content)
        os.replace(temporary, path)
    finally:
        if temporary is not None and temporary.exists():
            temporary.unlink()


def main():
    if not (ROOT / "app_v2.py").is_file():
        raise ValueError("app_v2.py がある clinic-list-filter-complete フォルダーへ、このファイルを置いてください。")
    changes = []
    for relative, spec in FILES.items():
        path = ROOT / relative
        before = normalized(path) if path.is_file() else None
        after = spec["content"]
        if path.suffix == ".py":
            compile(after, str(path), "exec")
        if before == after:
            continue
        digest = hashlib.sha256(before.encode("utf-8")).hexdigest() if before is not None else None
        if digest not in spec["before_sha256s"]:
            raise ValueError(relative + " の内容が対応版と異なります。上書きせず停止しました。表示された内容をお知らせください。")
        changes.append((relative, before, after))
    if not changes:
        print("この修正は適用済みです。アプリで対象5件の強制再調査を実行してください。")
        return

    backup = ROOT / ("code_backup_midday_procedure_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
    backup.mkdir()
    for relative, before, after in changes:
        if before is not None:
            target = backup / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ROOT / relative, target)
    written = []
    try:
        for relative, before, after in changes:
            atomic_write(ROOT / relative, after)
            written.append((relative, before))
    except BaseException:
        for relative, before in reversed(written):
            if before is None:
                (ROOT / relative).unlink(missing_ok=True)
            else:
                shutil.copy2(backup / relative, ROOT / relative)
        raise
    print("昼の検査・手術専用枠を加点項目に追加しました。")
    print("変更前コードの控え: " + backup.name)
    print("SQLite・元CSV・UUID・手動修正は変更していません。")
    print("起動後、自動情報収集で東京都・既存UUIDあり・5件・検索上限10・強制再調査オンを指定してください。")
    print("詳しい手順: docs/MIDDAY_PROCEDURE_SIGNAL.md")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("更新できませんでした: " + str(exc))
        sys.exit(1)
